use zil_base::{Diagnostic,FileId,Fingerprint,Limits,ModuleId,ResultCategory,SourceUnit,TargetProfile,json_string};
use zil_ir::{CoreImport,CoreProgram};
use std::{fmt::Debug,path::Path};
type Files=Vec<(String,String)>;
fn files(raw:&[(&str,&str)])->Files {raw.iter().map(|(n,s)|(n.to_string(),s.to_string())).collect()}
fn cases(root:&Path)->Vec<(&'static str,Files,bool)> {
    let nominal=files(&[
      ("main","import left\nimport right\nfn main()->i32{let a=left.make();let b=right.make();return a.get()+b.get()-42}"),
      ("left","pub struct C{v:i32} impl C{pub fn get(self:&Self)->i32=>.v} pub fn make()->C=>C{v:10}"),
      ("right","pub struct C{v:i32} impl C{pub fn get(self:&Self)->i32=>.v*2} pub fn make()->C=>C{v:16}")]);
    let defaults=files(&[
      ("main","import config\nimport consumer\nfn seed()->i64=>999\nfn value()->i64{let a=config.Cell{x:20};return a.n+consumer.get()}"),
      ("config","fn seed()->i64=>21\npub struct Cell{pub x:i64;pub n:i64=seed();}"),
      ("consumer","import config\npub fn get()->i64{let a=config.Cell{x:1};return a.n}")]);
    let callbacks=files(&[
      ("main","import first\nimport second\nfn main()->i32{let f=(x:i32)=>x+1;let g=(x:i32)=>x+2;return first.apply(&f,10)+second.apply(&g,20)}"),
      ("first","pub fn apply<F:Fn(i32)->i32>(f:&F,x:i32)->i32{return f(x)}"),
      ("second","pub fn apply<F:Fn(i32)->i32>(f:&F,x:i32)->i32{return f(x)}")]);
    let original_state:Files=["main","model","state"].into_iter().map(|n| (n.to_string(),std::fs::read_to_string(root.join(format!("crates/zil-driver/tests/impl197_cases/09-cross-module-copy-state/{n}.zil"))).unwrap())).collect();
    let mut state=original_state.clone();
    state.iter_mut().find(|(name,_)|name=="model").unwrap().1=state.iter().find(|(name,_)|name=="model").unwrap().1.replace("struct Data{n:","struct Data{pub n:");
    let mut reversed=nominal.clone();reversed.swap(1,2);
    vec![
      ("nominal-same-spelling",nominal,true),("nominal-reversed-modules",reversed,true),
      ("defining-default-and-two-callers",defaults,true),("same-generic-name-in-two-modules",callbacks,true),("copy-type-callable-state",state,true),
      ("original-private-copy-state",original_state,false),
      ("duplicate-local-record",files(&[("main","struct C{x:i32}struct C{y:i32}fn main()->i32=>0")]),false),
      ("private-default",files(&[("main","import config\nfn main()->i32{let a=config.Config{};return 0}"),("config","pub struct Config{x:i32=42}")]),false),
      ("unused-public-default-error",files(&[("main","import config\nfn main()->i32{let a=config.Config{x:42};return a.x}"),("config","pub struct Config{pub x:i32=missing();}")]),false),
      ("duplicate-field-before-later-module",files(&[("main","import first\nimport second\nfn main()->i32=>0"),("first","pub struct C{pub x:i32;pub x:i32}"),("second","pub struct C{pub y:Missing}")]),false),
      ("missing-binder-after-generic-request",files(&[("main","package State{manages bytes:ByteBuffer;callback:FreshF}fn main()->i32=>0")]),false),
    ]
}
fn digest<T:Debug>(value:&T)->String {Fingerprint::of(format!("{value:#?}").as_bytes()).to_hex()}
fn result<T:Debug>(value:&Result<T,Vec<Diagnostic>>)->String {match value{Ok(v)=>format!("{{\"status\":\"ok\",\"digest\":{}}}",json_string(&digest(v))),Err(e)=>format!("{{\"status\":\"error\",\"diagnostics\":[{}]}}",e.iter().map(Diagnostic::to_json).collect::<Vec<_>>().join(","))}}
fn boundary<T:Debug>(label:&str,maximum:usize,mut run:impl FnMut(usize)->Result<T,Vec<Diagnostic>>) {
    let expected=run(maximum).unwrap();let hash=digest(&expected);let(mut low,mut high)=(0,maximum);let mut probes=0;
    while low+1<high{let n=low+(high-low)/2;let actual=run(n);probes+=1;match actual {Ok(value)=>{assert_eq!(digest(&value),hash);high=n},Err(errors)=>{assert!(errors.iter().all(|e|e.category==ResultCategory::ResourceLimit),"{label} unexpected error at {n}: {errors:?}");low=n}}}
    let exact=run(high);assert_eq!(digest(exact.as_ref().unwrap()),hash);
    let below=run(high-1);assert!(below.is_err());let again=run(high);assert_eq!(digest(again.as_ref().unwrap()),hash);
    println!("{{\"kind\":\"boundary\",\"label\":{},\"n\":{high},\"binary_search_queries\":{probes},\"exact\":{},\"below\":{},\"fresh_exact\":{}}}",json_string(label),result(&exact),result(&below),result(&again));
}
fn main(){
    let root=std::env::args().nth(1).unwrap();let defaults=Limits::default();let mut positives=0;
    for (name,entries,expected_success) in cases(Path::new(&root)) {
      let sources=entries.iter().enumerate().map(|(i,(name,text))|SourceUnit::new(FileId(i as u32),ModuleId(i as u32),format!("{name}.zil"),text)).collect::<Vec<_>>();
      let syntax=sources.iter().map(|s|zil_syntax::parse(s).into_result().unwrap()).collect::<Vec<_>>();
      let imports=syntax.iter().map(|m|m.items.iter().filter_map(|i|if let zil_syntax::ast::ItemKind::Import(import)=&i.kind {
        let index=entries.iter().position(|(name,_)|import.path==[name.clone()]).unwrap();Some(CoreImport{alias:import.alias.clone().unwrap_or_else(||import.path.last().unwrap().clone()),module:ModuleId(index as u32),span:i.span})
      }else{None}).collect::<Vec<_>>()).collect::<Vec<_>>();
      let refs=syntax.iter().collect::<Vec<_>>();
      let expand=|limits:&Limits|zil_expand::expand_program_with_limits(&sources,&refs,&imports,limits);
      let expanded=expand(&defaults);println!("{{\"kind\":\"expand\",\"case\":{},\"input_digest\":{},\"result\":{}}}",json_string(name),json_string(&digest(&entries)),result(&expanded));
      if let Ok(expanded)=expanded {
        for (_,map) in &expanded{map.validate(&sources,&defaults).unwrap();}
        let program=CoreProgram{root:ModuleId(0),source_fingerprint:Fingerprint::of(name.as_bytes()),modules:expanded.iter().map(|(m,_)|m.clone()).collect()};
        let typed=zil_types::check_program(&program,&TargetProfile::host_llvm(),&defaults);
        println!("{{\"kind\":\"types\",\"case\":{},\"result\":{}}}",json_string(name),result(&typed));
        assert_eq!(typed.is_ok(),expected_success,"{name}: {typed:?}");
        if expected_success {
          positives+=1;
          boundary(&format!("{name}:expand-work"),defaults.max_analysis_steps,|n|expand(&Limits{max_analysis_steps:n,..defaults.clone()}));
          boundary(&format!("{name}:types-work"),defaults.max_analysis_steps,|n|zil_types::check_program(&program,&TargetProfile::host_llvm(),&Limits{max_analysis_steps:n,..defaults.clone()}));
          if name=="defining-default-and-two-callers"{boundary(&format!("{name}:expand-nodes"),defaults.max_nodes,|n|expand(&Limits{max_nodes:n,..defaults.clone()}));}
        }
      } else {assert!(!expected_success,"{name}: {expanded:?}");}
    }
    assert_eq!(positives,5);
    println!("{{\"kind\":\"summary\",\"source_cases\":11,\"positive_cases\":5,\"budget_boundaries\":11}}");
}

